from pathlib import Path
from docx import Document
from docx.enum.text import WD_COLOR_INDEX
from docx.oxml import OxmlElement
from docx.text.paragraph import Paragraph
p=Path(__file__).parent; previous=p.parent/'reviewer1_comment2'
def new_after(anchor,text,style=None):
 e=OxmlElement('w:p');anchor._p.addnext(e);q=Paragraph(e,anchor._parent);q.style=style or anchor.style;q.add_run(text).font.highlight_color=WD_COLOR_INDEX.YELLOW;return q
def new_before(anchor,text,style=None):
 e=OxmlElement('w:p');anchor._p.addprevious(e);q=Paragraph(e,anchor._parent);q.style=style or 'Normal';q.add_run(text).font.highlight_color=WD_COLOR_INDEX.YELLOW;return q
def find(d,s):
 r=[x for x in d.paragraphs if s in x.text];assert len(r)==1,(s,len(r));return r[0]
def repl(d,old,new):
 matches=[r for x in d.paragraphs for r in x.runs if old in r.text];assert len(matches)==1,old;r=matches[0];r.text=r.text.replace(old,new);r.font.highlight_color=WD_COLOR_INDEX.YELLOW
m=Document(previous/'Manuscript_comment2_closed.docx')
repl(m,'The representation and acquisition components use different feature matrices and validation schemes and are assessed as complementary but separate analyses; their improvements are neither additive nor evidence that pose features caused the ordering advantage.','The original representation and acquisition comparisons use different feature matrices and validation schemes. A subsequent matched factorial analysis examines their combination and whether the ordering effect changes with the representation.')
repl(m,'position catalyst-contextual representation and acquisition as complementary, separately tested components.','show that the effect of ordering can depend on representation under the tested retrospective protocol; the combined full-pose/acquisition model did not outperform the structure-only models on average.')
abstract=m.paragraphs[5];run=abstract.add_run(' A matched factorial analysis found that ordering effects depended on representation, while the full-pose/acquisition combination had higher mean held-out error than structure-only models in both datasets.');run.font.highlight_color=WD_COLOR_INDEX.YELLOW
new_after(find(m,'Uncertainty–diversity prioritises candidates'), 'A matched factorial analysis crossed structure-only RDKit/Morgan features with or without all 248 Stage 2p fields against source-order continuation or uncertainty–diversity acquisition, using the common-test splits, starting pairs and label budgets described below. The candidate prediction models used the corresponding feature set, whereas molecular novelty and Tanimoto-kNN remained fingerprint-based. Ridge held-out MAE was averaged across five budgets and three starts per split. Random continuations provided a secondary comparison (SI Section S10). The full Stage 2p block and Ridge protocol differ from the selected-feature Elastic Net representation benchmark.')
new_after(find(m,'Against the same held-out source-order continuation'), 'In the matched factorial analysis, mean held-out MAE for structure/source, structure/acquisition, full-pose/source and full-pose/acquisition was 11.34, 12.07, 16.72 and 13.88 ee points for Fe(P7)Cl, and 9.62, 10.77, 15.70 and 14.27 for Fe(CMC-Por)Cl, respectively. Source-order-minus-acquisition differences were −0.73 and −1.15 for structure-only versus 2.85 and 1.43 for full-pose models. Thus the ordering effect varied with representation in these data, but the full-pose/acquisition combination had higher mean error than both structure-only cells. Overlapping splits do not establish a population-level interaction or general synergy (SI Section S10).')
m.save(p/'Manuscript_comment3_revised.docx')
s=Document(previous/'Supporting_Information_comment2_closed.docx')
anchor=find(s,'Declaration of AI-assisted manuscript preparation')
new_before(anchor,'S10 Representation and acquisition factorial comparison','Heading 1')
new_before(anchor,'The 20 common-test splits and three shared starting pairs per split from Section S8 were reused. Each representation was crossed with source-order continuation and uncertainty–diversity ordering. Structure-only comprised 15 RDKit descriptors and 1,024 Morgan bits; full-pose added all 248 Stage 2p fields. At each step, Ridge and Elastic Net candidate predictions used the cell representation, while fingerprint novelty, Tanimoto-kNN and family coverage followed the original rule. Source order and three seeded random continuations were shared between representations. Held-out Ridge MAE was averaged across 2, 6, 10, 15 and 20 labels and the three starts within each split. CMC-Por locked audit records were excluded. This protocol differs from the selected-feature Elastic Net representation benchmark.')
new_before(anchor,'Mean held-out MAEs in ee points, in the order structure/source, structure/acquisition, full-pose/source and full-pose/acquisition, were 11.34, 12.07, 16.72 and 13.88 for Fe(P7)Cl and 9.62, 10.77, 15.70 and 14.27 for Fe(CMC-Por)Cl. For structure-only, source-order-minus-acquisition differences averaged −0.73 and −1.15, with 7/20 and 3/20 splits favouring acquisition; for full-pose they averaged 2.85 and 1.43, with 17/20 and 11/20 splits favouring acquisition. The interaction contrast, structure-only ordering benefit minus full-pose ordering benefit, averaged −3.58 and −2.58 ee points; 18/20 and 14/20 splits had a larger benefit with full-pose. The full-pose/acquisition cell had higher average error than both structure-only cells in each catalyst, although it improved on full-pose/source.')
new_before(anchor,'Against the random continuation mean, random-minus-acquisition differences were −1.20 and −0.56 ee points for structure-only and 0.37 and 1.06 for full-pose, for Fe(P7)Cl and Fe(CMC-Por)Cl respectively. The full split-level results, selected sequences, held-out predictions and checks are retained in the accompanying revision analysis. These overlapping splits share the same small datasets; the contrasts are descriptive and neither demonstrate statistical significance nor establish a general interaction. This analysis addresses ee under one model and acquisition protocol; it does not establish performance for yield, other feature selections, or prospective experiments.')
